    imageAlt: "Равноудаленный закупочный кооператив: принципы работы",
    heroImageSrc: "/landing/media/articles/equidistant-cooperative-hero.jpeg",
    heroImageAlt: "Равноудаленный закупочный кооператив: принципы работы",
    tag: "news",
